begin;
create type public.app_role as enum ('admin','client');
create type public.inquiry_status as enum ('new','reviewing','contacted','quoted','converted','closed');
create type public.project_status as enum ('planning','scheduled','in_progress','on_hold','completed','cancelled');
create type public.milestone_status as enum ('pending','in_progress','completed');
create type public.quotation_status as enum ('draft','issued','accepted','declined','expired','superseded');
create or replace function public.set_updated_at() returns trigger language plpgsql set search_path=public as $$ begin new.updated_at=now(); return new; end $$;
create table public.profiles(user_id uuid primary key references auth.users(id) on delete cascade,email text not null unique,display_name text not null default '',phone text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.user_roles(user_id uuid primary key references auth.users(id) on delete cascade,role public.app_role not null,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create or replace function public.handle_auth_user() returns trigger language plpgsql security definer set search_path=public,auth as $$ begin insert into public.profiles(user_id,email,display_name) values(new.id,lower(new.email),coalesce(new.raw_user_meta_data->>'name','')) on conflict(user_id) do update set email=lower(excluded.email),updated_at=now(); return new; end $$;
create trigger on_auth_user_created after insert or update of email on auth.users for each row execute function public.handle_auth_user();
create or replace function public.is_admin() returns boolean language sql stable security definer set search_path=public,auth as $$ select exists(select 1 from public.user_roles r where r.user_id=auth.uid() and r.role='admin') $$;
create or replace function public.has_client_role() returns boolean language sql stable security definer set search_path=public,auth as $$ select exists(select 1 from public.user_roles r where r.user_id=auth.uid() and r.role='client') $$;
create table public.inquiries(id uuid primary key default gen_random_uuid(),public_reference text not null unique,full_name text not null,email text not null,phone text not null,project_type text not null,project_location text not null,budget_range text,desired_start_date date,description text not null,privacy_acknowledged boolean not null default false,status public.inquiry_status not null default 'new',idempotency_key uuid not null unique,converted_client_id uuid,converted_project_id uuid,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create index inquiries_status_created_idx on public.inquiries(status,created_at desc);
create index inquiries_email_idx on public.inquiries(email);
create table public.inquiry_notes(id uuid primary key default gen_random_uuid(),inquiry_id uuid not null references public.inquiries(id) on delete cascade,author_id uuid not null references auth.users(id),note text not null,created_at timestamptz not null default now());
create table public.clients(id uuid primary key default gen_random_uuid(),name text not null,email text not null unique,phone text,company_name text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.client_memberships(id uuid primary key default gen_random_uuid(),client_id uuid not null references public.clients(id) on delete cascade,user_id uuid not null references auth.users(id) on delete cascade,created_at timestamptz not null default now(),unique(client_id,user_id));
create index client_memberships_user_idx on public.client_memberships(user_id);
create table public.projects(id uuid primary key default gen_random_uuid(),title text not null,client_id uuid references public.clients(id) on delete set null,service_type text not null,location text,description text not null default '',planned_start_date date,planned_completion_date date,actual_completion_date date,status public.project_status not null default 'planning',created_by uuid references auth.users(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create index projects_client_status_idx on public.projects(client_id,status);
create table public.project_memberships(project_id uuid not null references public.projects(id) on delete cascade,user_id uuid not null references auth.users(id) on delete cascade,created_at timestamptz not null default now(),primary key(project_id,user_id));
create or replace function public.sync_project_memberships() returns trigger language plpgsql security definer set search_path=public as $$ begin if new.client_id is not null then insert into public.project_memberships(project_id,user_id) select new.id,cm.user_id from public.client_memberships cm where cm.client_id=new.client_id on conflict do nothing; end if; return new; end $$;
create trigger project_memberships_after_insert after insert or update of client_id on public.projects for each row execute function public.sync_project_memberships();
create or replace function public.is_project_member(p_project_id uuid) returns boolean language sql stable security definer set search_path=public,auth as $$ select exists(select 1 from public.project_memberships pm where pm.project_id=p_project_id and pm.user_id=auth.uid()) $$;
create table public.milestones(id uuid primary key default gen_random_uuid(),project_id uuid not null references public.projects(id) on delete cascade,title text not null,description text not null default '',display_order integer not null default 0,target_date date,status public.milestone_status not null default 'pending',completion_date date,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),check(status='completed' or completion_date is null));
create index milestones_project_order_idx on public.milestones(project_id,display_order);
create table public.project_updates(id uuid primary key default gen_random_uuid(),project_id uuid not null references public.projects(id) on delete cascade,author_id uuid not null references auth.users(id),content text not null,client_visible boolean not null default false,created_at timestamptz not null default now());
create table public.project_internal_notes(id uuid primary key default gen_random_uuid(),project_id uuid not null references public.projects(id) on delete cascade,author_id uuid not null references auth.users(id),note text not null,created_at timestamptz not null default now());
create table public.project_photos(id uuid primary key default gen_random_uuid(),project_id uuid not null references public.projects(id) on delete cascade,bucket_id text not null default 'project-private',storage_path text not null unique,alt_text text not null default '',is_client_visible boolean not null default false,created_at timestamptz not null default now());
create table public.project_documents(id uuid primary key default gen_random_uuid(),project_id uuid not null references public.projects(id) on delete cascade,bucket_id text not null default 'project-private',storage_path text not null unique,title text not null,original_mime text not null default 'application/pdf',is_client_visible boolean not null default false,created_at timestamptz not null default now());
create table public.quotations(id uuid primary key default gen_random_uuid(),quotation_number text not null,revision integer not null default 1,client_id uuid not null references public.clients(id),inquiry_id uuid references public.inquiries(id) on delete set null,project_id uuid references public.projects(id) on delete set null,status public.quotation_status not null default 'draft',currency char(3) not null default 'PHP' check(currency='PHP'),issued_at timestamptz,valid_until date,scope_of_work text not null,terms text not null default '',notes_visible_to_client text not null default '',subtotal numeric(16,2) not null default 0,discount_amount numeric(16,2) not null default 0,tax_label text,tax_rate_percent numeric(7,4) not null default 0,tax_amount numeric(16,2) not null default 0,grand_total numeric(16,2) not null default 0,response_by uuid references auth.users(id),responded_at timestamptz,created_by uuid references auth.users(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(quotation_number,revision),check(discount_amount>=0 and tax_rate_percent between 0 and 100 and subtotal>=0 and tax_amount>=0 and grand_total>=0));
create index quotations_client_status_idx on public.quotations(client_id,status,created_at desc);
create table public.quotation_items(id uuid primary key default gen_random_uuid(),quotation_id uuid not null references public.quotations(id) on delete cascade,category text not null check(category in ('Materials','Labor','Equipment','Other')),description text not null,quantity numeric(12,3) not null check(quantity>0),unit text not null,unit_price numeric(16,2) not null check(unit_price>=0),amount numeric(16,2) not null check(amount>=0),display_order integer not null default 0,created_at timestamptz not null default now());
create index quotation_items_order_idx on public.quotation_items(quotation_id,display_order);
create table public.portfolio_entries(id uuid primary key default gen_random_uuid(),title text not null,slug text not null unique,description text not null,category text not null,approved_location_display text,highlights jsonb not null default '[]'::jsonb check(jsonb_typeof(highlights)='array'),is_concept boolean not null default false,is_published boolean not null default false,archived_at timestamptz,admin_notes text,created_by uuid references auth.users(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create index portfolio_public_idx on public.portfolio_entries(is_published,archived_at,created_at desc);
create table public.portfolio_images(id uuid primary key default gen_random_uuid(),portfolio_entry_id uuid not null references public.portfolio_entries(id) on delete cascade,bucket_id text not null default 'portfolio-assets',storage_path text not null unique,alt_text text not null,display_order integer not null default 0,created_at timestamptz not null default now());
create index portfolio_images_order_idx on public.portfolio_images(portfolio_entry_id,display_order);
create table public.services(id uuid primary key default gen_random_uuid(),name text not null,slug text not null unique,description text not null,display_order integer not null default 0,is_active boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
insert into public.services(name,slug,description,display_order) values
('Residential Construction','residential-construction','Purposeful spaces shaped around the people who live in them.',1),
('Commercial Construction','commercial-construction','Considered environments for work, business, and the people they serve.',2),
('Renovation & Fit-Out','renovation-fit-out','Careful improvements that make existing spaces work harder.',3),
('Project Management','project-management','Clear coordination from the first conversation to the final handover.',4);
create table public.company_settings(id smallint primary key default 1 check(id=1),currency char(3) not null default 'PHP' check(currency='PHP'),default_tax_label text,default_tax_rate_percent numeric(7,4) check(default_tax_rate_percent between 0 and 100),updated_by uuid references auth.users(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.activity_logs(id uuid primary key default gen_random_uuid(),actor_id uuid references auth.users(id) on delete set null,resource_type text not null,resource_id uuid,action text not null,created_at timestamptz not null default now());
create index activity_logs_created_idx on public.activity_logs(created_at desc);
create table public.submission_rate_limits(rate_key_hash text primary key,window_started_at timestamptz not null,attempt_count integer not null check(attempt_count>=0),updated_at timestamptz not null default now());
-- Activity records intentionally contain no request bodies, passwords, tokens, or quotation content.
create or replace function public.log_admin_change() returns trigger language plpgsql security definer set search_path=public,auth as $$ declare rid uuid; act text; begin if not public.is_admin() then return coalesce(new,old); end if; rid=coalesce(new.id,old.id); act=lower(tg_op); if tg_op='UPDATE' then act='updated'; elsif tg_op='INSERT' then act='created'; end if; insert into public.activity_logs(actor_id,resource_type,resource_id,action) values(auth.uid(),tg_table_name,rid,act); return coalesce(new,old); end $$;
create trigger activity_inquiries after insert or update on public.inquiries for each row execute function public.log_admin_change();
create trigger activity_clients after insert or update on public.clients for each row execute function public.log_admin_change();
create trigger activity_projects after insert or update on public.projects for each row execute function public.log_admin_change();
create trigger activity_quotations after insert or update on public.quotations for each row execute function public.log_admin_change();
create trigger activity_portfolio after insert or update on public.portfolio_entries for each row execute function public.log_admin_change();
create trigger activity_services after insert or update on public.services for each row execute function public.log_admin_change();
-- updated_at triggers.
do $$ declare t text; begin foreach t in array array['profiles','user_roles','clients','projects','milestones','quotations','portfolio_entries','services','company_settings','inquiries'] loop execute format('create trigger %I before update on public.%I for each row execute function public.set_updated_at()',t||'_updated_at',t); end loop; end $$;
-- RLS is enabled on every exposed business table.
do $$ declare t text; begin foreach t in array array['profiles','user_roles','inquiries','inquiry_notes','clients','client_memberships','projects','project_memberships','milestones','project_updates','project_internal_notes','project_photos','project_documents','quotations','quotation_items','portfolio_entries','portfolio_images','services','company_settings','activity_logs','submission_rate_limits'] loop execute format('alter table public.%I enable row level security',t); end loop; end $$;
create policy profile_read_self_admin on public.profiles for select to authenticated using(user_id=auth.uid() or public.is_admin());
create policy profile_update_self on public.profiles for update to authenticated using(user_id=auth.uid()) with check(user_id=auth.uid());
create policy role_read_self_admin on public.user_roles for select to authenticated using(user_id=auth.uid() or public.is_admin());
create policy inquiry_admin_only on public.inquiries for all to authenticated using(public.is_admin()) with check(public.is_admin());
create policy inquiry_notes_admin_only on public.inquiry_notes for all to authenticated using(public.is_admin()) with check(public.is_admin());
create policy clients_admin_all on public.clients for all to authenticated using(public.is_admin()) with check(public.is_admin());
create policy clients_read_member on public.clients for select to authenticated using(exists(select 1 from public.client_memberships cm where cm.client_id=id and cm.user_id=auth.uid()));
create policy client_memberships_admin_all on public.client_memberships for all to authenticated using(public.is_admin()) with check(public.is_admin());
create policy client_memberships_read_self on public.client_memberships for select to authenticated using(user_id=auth.uid());
create policy projects_admin_all on public.projects for all to authenticated using(public.is_admin()) with check(public.is_admin());
create policy projects_client_read on public.projects for select to authenticated using(public.is_project_member(id));
create policy project_memberships_admin_all on public.project_memberships for all to authenticated using(public.is_admin()) with check(public.is_admin());
create policy project_memberships_self_read on public.project_memberships for select to authenticated using(user_id=auth.uid());
create policy milestones_admin_all on public.milestones for all to authenticated using(public.is_admin()) with check(public.is_admin());
create policy milestones_member_read on public.milestones for select to authenticated using(public.is_project_member(project_id));
create policy project_updates_admin_all on public.project_updates for all to authenticated using(public.is_admin()) with check(public.is_admin());
create policy project_updates_visible_read on public.project_updates for select to authenticated using(client_visible and public.is_project_member(project_id));
create policy project_internal_notes_admin on public.project_internal_notes for all to authenticated using(public.is_admin()) with check(public.is_admin());
create policy project_photos_admin on public.project_photos for all to authenticated using(public.is_admin()) with check(public.is_admin());
create policy project_photos_visible on public.project_photos for select to authenticated using(is_client_visible and public.is_project_member(project_id));
create policy project_documents_admin on public.project_documents for all to authenticated using(public.is_admin()) with check(public.is_admin());
create policy project_documents_visible on public.project_documents for select to authenticated using(is_client_visible and public.is_project_member(project_id));
create policy quotations_admin_all on public.quotations for all to authenticated using(public.is_admin()) with check(public.is_admin());
create policy quotations_client_read on public.quotations for select to authenticated using(status<>'draft' and exists(select 1 from public.client_memberships cm where cm.client_id=quotations.client_id and cm.user_id=auth.uid()));
create policy quotation_items_admin_all on public.quotation_items for all to authenticated using(public.is_admin()) with check(public.is_admin());
create policy quotation_items_client_read on public.quotation_items for select to authenticated using(exists(select 1 from public.quotations q join public.client_memberships cm on cm.client_id=q.client_id where q.id=quotation_id and q.status<>'draft' and cm.user_id=auth.uid()));
create policy portfolio_public_read on public.portfolio_entries for select to anon,authenticated using(is_published and archived_at is null);
create policy portfolio_admin_all on public.portfolio_entries for all to authenticated using(public.is_admin()) with check(public.is_admin());
create policy portfolio_images_public_read on public.portfolio_images for select to anon,authenticated using(exists(select 1 from public.portfolio_entries pe where pe.id=portfolio_entry_id and pe.is_published and pe.archived_at is null));
create policy portfolio_images_admin_all on public.portfolio_images for all to authenticated using(public.is_admin()) with check(public.is_admin());
create policy services_public_read on public.services for select to anon,authenticated using(is_active);
create policy services_admin_all on public.services for all to authenticated using(public.is_admin()) with check(public.is_admin());
create policy settings_admin_all on public.company_settings for all to authenticated using(public.is_admin()) with check(public.is_admin());
create policy activity_admin_read on public.activity_logs for select to authenticated using(public.is_admin());
create policy rate_limits_service_only on public.submission_rate_limits for all to service_role using(true) with check(true);
-- Explicit grants: no anonymous inquiry read or authenticated direct rate-limit access.
grant usage on schema public to anon,authenticated,service_role;
grant select on public.services,public.portfolio_entries,public.portfolio_images to anon,authenticated;
grant select on public.profiles,public.user_roles,public.clients,public.client_memberships,public.projects,public.project_memberships,public.milestones,public.project_updates,public.project_photos,public.project_documents,public.quotations,public.quotation_items,public.inquiry_notes,public.activity_logs,public.company_settings to authenticated;
grant update(display_name,phone) on public.profiles to authenticated;
grant insert,update,delete on public.clients,public.projects,public.milestones,public.project_updates,public.project_internal_notes,public.project_photos,public.project_documents,public.quotations,public.quotation_items,public.portfolio_entries,public.portfolio_images,public.services,public.company_settings,public.inquiries,public.inquiry_notes to authenticated;
grant select,insert,update,delete on all tables in schema public to service_role;
grant execute on function public.is_admin(),public.has_client_role(),public.is_project_member(uuid) to authenticated;
commit;
